#include "lab.h"
#include <algorithm>
#include <chrono>
#include <limits>
#include <bit>
namespace paintlab {
V Mesh::position(Anchor a)const {if(a.face>=faces.size())throw std::runtime_error("Invalid face");auto f=faces[a.face];return vertices[f[0]]*a.bary.x+vertices[f[1]]*a.bary.y+vertices[f[2]]*a.bary.z;}
std::uint64_t Mesh::topology()const{std::uint64_t h=1469598103934665603ULL;for(auto f:faces)for(auto v:f){h^=v;h*=1099511628211ULL;}h^=vertices.size();return h;}
std::uint64_t Mesh::fingerprint()const{auto h=topology();for(auto v:vertices)for(double x:{v.x,v.y,v.z}){h^=std::bit_cast<std::uint64_t>(x==0?0.:x);h*=1099511628211ULL;}return h;}
Frame::Frame(const Mesh& m){if(m.faces.empty())throw std::runtime_error("Empty receiver");auto f=m.faces[0];origin=m.vertices[f[0]];u=unit(m.vertices[f[1]]-origin);n=unit(cross(u,m.vertices[f[2]]-origin));v=cross(n,u);
 for(auto face:m.faces){auto a=m.vertices[face[0]],b=m.vertices[face[1]],c=m.vertices[face[2]];auto normal=cross(b-a,c-a);if(length(normal)<1e-12)continue;if(dot(unit(normal),n)<.05)throw std::runtime_error("This projected method requires a consistently facing single-valued surface. Use C or D for spheres/folds.");}}
double influence(V p,const Segment& s){V ab=s.b.p-s.a.p,ap=p-s.a.p;double A=dot(ap,ap),B=dot(ap,ab),C=dot(ab,ab),k=s.b.radius-s.a.radius;
 // Minimize squared distance / squared interpolated radius over the sweep.
 double denom=C*s.a.radius+k*B,t=std::abs(denom)>1e-20?std::clamp((B*s.a.radius+k*A)/denom,0.,1.):0;
 auto ratio=[&](double u){double r=s.a.radius+k*u;return length(ap-ab*u)/r;};double d=std::min({ratio(0),ratio(1),ratio(t)});if(d>1)return 0;return s.settings.strength*(s.settings.softness==0?1:std::clamp((1-d)/s.settings.softness,0.,1.));}
std::unique_ptr<Kernel> make(int i,const Mesh& m,double r){if(!std::isfinite(r)||r<=0)throw std::runtime_error("Resolution must be positive");switch(i){case 1:return makeVector(m,r);case 2:return makeMask(m,r);case 3:return makeVolumes(m,r);case 4:return makeField(m,r);default:throw std::runtime_error("Unknown method");}}
Session::Session(int i,Mesh m,double r):method_(i),mesh_(std::move(m)),resolution_(r),state_(make(i,mesh_,r)){}
void Session::begin(Settings s){if(pending_)throw std::runtime_error("Finish current gesture");if(!std::isfinite(s.strength)||s.strength<0||s.strength>1||!std::isfinite(s.softness)||s.softness<0||s.softness>1)throw std::runtime_error("Invalid brush settings");auto next=state_->clone();next->begin(s);pending_=std::move(next);}
void Session::append(Hit h){if(!pending_)throw std::runtime_error("Begin gesture first");if(!std::isfinite(h.radius)||h.radius<=0||!std::isfinite(h.p.x)||!std::isfinite(h.p.y)||!std::isfinite(h.p.z))throw std::runtime_error("Invalid brush hit");mesh_.position(h.anchor);try{pending_->append(h);if(pending_->stats().bytes>128*1024*1024)throw std::runtime_error("128 MiB state limit; edit cancelled");}catch(...){cancel();throw;}}
void Session::commit(){if(!pending_)return;pending_->end();if(historyBytes()+pending_->stats().bytes>512*1024*1024){cancel();throw std::runtime_error("512 MiB state/history budget reached; edit cancelled");}undo_.push_back(std::move(state_));state_=std::move(pending_);redo_.clear();}
void Session::cancel(){pending_.reset();}void Session::undo(){cancel();if(undo_.empty())return;redo_.push_back(std::move(state_));state_=std::move(undo_.back());undo_.pop_back();}void Session::redo(){cancel();if(redo_.empty())return;undo_.push_back(std::move(state_));state_=std::move(redo_.back());redo_.pop_back();}
void Session::clear(){cancel();auto empty=make(method_,mesh_,resolution_);undo_.push_back(std::move(state_));state_=std::move(empty);redo_.clear();}
std::size_t Session::historyBytes()const{std::size_t n=state_->stats().bytes;for(auto& k:undo_)n+=k->stats().bytes;for(auto& k:redo_)n+=k->stats().bytes;return n;}
std::string Session::save()const{if(active())throw std::runtime_error("Finish gesture before saving");std::ostringstream o;o.precision(17);o<<"PAINTLAB 1 "<<method_<<' '<<mesh_.fingerprint()<<' '<<resolution_<<'\n'<<state_->save();return o.str();}
void Session::load(const std::string& b){if(b.size()>128*1024*1024)throw std::runtime_error("File limit");std::istringstream in(b);std::string magic;int version,method;std::uint64_t geometry;double res;if(!(in>>magic>>version>>method>>geometry>>res)||magic!="PAINTLAB"||version!=1||method!=method_||geometry!=mesh_.fingerprint()||res!=resolution_)throw std::runtime_error("File method/geometry/resolution mismatch");std::string rest((std::istreambuf_iterator<char>(in)),{});auto next=make(method_,mesh_,resolution_);next->load(rest);if(next->stats().bytes>128*1024*1024)throw std::runtime_error("File state limit");cancel();undo_.push_back(std::move(state_));state_=std::move(next);redo_.clear();}
Preview preview(const Session& s,bool showPoints,bool showFill,double step){if(!std::isfinite(step)||step<=0)throw std::runtime_error("Invalid display step");using Clock=std::chrono::steady_clock;auto start=Clock::now();Preview out;auto& mesh=s.mesh();auto& field=s.view();out.lines=field.exactBoundary();bool needLines=out.lines.empty();std::size_t total=0;
 // Independent of canonical state: bounded-resolution complete mesh subdivision.
 // Refuse excessive display instead of publishing only its first triangles.
 for(auto f:mesh.faces){double longest=std::max({length(mesh.vertices[f[1]]-mesh.vertices[f[0]]),length(mesh.vertices[f[2]]-mesh.vertices[f[0]]),length(mesh.vertices[f[2]]-mesh.vertices[f[1]])});double wanted=std::ceil(longest/step);if(wanted>2048)throw std::runtime_error("Preview resolution exceeds limit; increase Display step (paint is retained)");auto n=std::max(1,int(wanted));if(total+std::size_t(n)*n>300000)throw std::runtime_error("Preview resolution exceeds 300k cells; increase Display step (paint is retained)");total+=std::size_t(n)*n;}
 for(unsigned face=0;face<mesh.faces.size();++face){auto f=mesh.faces[face];double longest=std::max({length(mesh.vertices[f[1]]-mesh.vertices[f[0]]),length(mesh.vertices[f[2]]-mesh.vertices[f[0]]),length(mesh.vertices[f[2]]-mesh.vertices[f[1]])});int n=std::max(1,int(std::ceil(longest/step)));
  auto emit=[&](V ba,V bb,V bc){Anchor aa{face,ba},ab{face,bb},ac{face,bc};V a=mesh.position(aa),b=mesh.position(ab),c=mesh.position(ac);double va=field.query(aa,a),vb=field.query(ab,b),vc=field.query(ac,c);Anchor center{face,(ba+bb+bc)*(1./3)};double weight=field.query(center,mesh.position(center));if(weight>0){V offset=unit(cross(b-a,c-a))*std::max(.01,step*.001);if(showFill){out.fill.push_back({a+offset,b+offset,c+offset});out.fillWeights.push_back(weight);}if(showPoints){out.points.push_back(mesh.position(center)+offset);out.pointWeights.push_back(weight);}}
   if(needLines){std::vector<V> cuts;auto cut=[&](V p,V q,double x,double y){if((x>.5)!=(y>.5))cuts.push_back(p+(q-p)*((.5-x)/(y-x)));};cut(a,b,va,vb);cut(b,c,vb,vc);cut(c,a,vc,va);if(cuts.size()==2)out.lines.push_back({cuts[0],cuts[1]});}};
  for(int i=0;i<n;++i)for(int j=0;j<n-i;++j){auto bary=[&](int x,int y){return V{1.-double(x+y)/n,double(x)/n,double(y)/n};};emit(bary(i,j),bary(i+1,j),bary(i,j+1));if(i+j+1<n)emit(bary(i+1,j),bary(i+1,j+1),bary(i,j+1));}}
 out.queryMs=std::chrono::duration<double,std::milli>(Clock::now()-start).count();return out;}
}
